import React from "react";

/**
 * شعار جملة المتحرك لشاشة الدخول — كل قطعة تدخل بحركة ثلاثية الأبعاد من اتجاه مختلف
 * وتتجمع في مكانها، وبعدها يفضل الشعار يتحرك بهدوء (دوران خفيف + عمق) لين يتم الدخول.
 * ملف مستقل: ما يحتاج أي مكتبة إضافية.
 */
const LOGO_RATIO = 344 / 700;

const PIECES = [
  { k: "J", l: 0.0000, t: 0.0000, w: 35.5714, src: "data:image/png;base64," },
  { k: "AR", l: 42.8571, t: 14.2442, w: 49.2857, src: "data:image/png;base64," },
  { k: "O", l: 34.7143, t: 47.0930, w: 13.4286, src: "data:image/png;base64," },
  { k: "M", l: 52.0000, t: 47.0930, w: 16.4286, src: "data:image/png;base64," },
  { k: "L", l: 72.7143, t: 47.0930, w: 11.0000, src: "data:image/png;base64," },
  { k: "A", l: 85.8571, t: 47.0930, w: 14.1429, src: "data:image/png;base64," },
];

const CSS = `
@keyframes jl-fly-J{0%{transform:translate3d(-420px,-240px,-760px) rotateX(10deg) rotateY(110deg) rotateZ(-40deg) scale(.35);opacity:0}35%{opacity:1}100%{transform:translate3d(0,0,0) rotateX(0) rotateY(0) rotateZ(0) scale(1);opacity:1}}
@keyframes jl-depth-J{0%{transform:translateZ(0)}100%{transform:translateZ(38px)}}
.jl-p-J{animation:jl-fly-J 1.35s cubic-bezier(.2,.85,.25,1.12) 0.0s both}
.jl-p-J img{animation:jl-depth-J 6.9s ease-in-out 2.4s infinite alternate}
@keyframes jl-fly-AR{0%{transform:translate3d(0px,-360px,-560px) rotateX(-85deg) rotateY(0deg) rotateZ(15deg) scale(.35);opacity:0}35%{opacity:1}100%{transform:translate3d(0,0,0) rotateX(0) rotateY(0) rotateZ(0) scale(1);opacity:1}}
@keyframes jl-depth-AR{0%{transform:translateZ(0)}100%{transform:translateZ(64px)}}
.jl-p-AR{animation:jl-fly-AR 1.35s cubic-bezier(.2,.85,.25,1.12) 0.25s both}
.jl-p-AR img{animation:jl-depth-AR 8.2s ease-in-out 2.4s infinite alternate}
@keyframes jl-fly-O{0%{transform:translate3d(-300px,300px,-640px) rotateX(60deg) rotateY(-30deg) rotateZ(130deg) scale(.35);opacity:0}35%{opacity:1}100%{transform:translate3d(0,0,0) rotateX(0) rotateY(0) rotateZ(0) scale(1);opacity:1}}
@keyframes jl-depth-O{0%{transform:translateZ(0)}100%{transform:translateZ(22px)}}
.jl-p-O{animation:jl-fly-O 1.35s cubic-bezier(.2,.85,.25,1.12) 0.45s both}
.jl-p-O img{animation:jl-depth-O 6.1s ease-in-out 2.4s infinite alternate}
@keyframes jl-fly-M{0%{transform:translate3d(0px,420px,-820px) rotateX(95deg) rotateY(0deg) rotateZ(-20deg) scale(.35);opacity:0}35%{opacity:1}100%{transform:translate3d(0,0,0) rotateX(0) rotateY(0) rotateZ(0) scale(1);opacity:1}}
@keyframes jl-depth-M{0%{transform:translateZ(0)}100%{transform:translateZ(46px)}}
.jl-p-M{animation:jl-fly-M 1.35s cubic-bezier(.2,.85,.25,1.12) 0.6s both}
.jl-p-M img{animation:jl-depth-M 7.3s ease-in-out 2.4s infinite alternate}
@keyframes jl-fly-L{0%{transform:translate3d(300px,300px,-640px) rotateX(-40deg) rotateY(-95deg) rotateZ(-90deg) scale(.35);opacity:0}35%{opacity:1}100%{transform:translate3d(0,0,0) rotateX(0) rotateY(0) rotateZ(0) scale(1);opacity:1}}
@keyframes jl-depth-L{0%{transform:translateZ(0)}100%{transform:translateZ(18px)}}
.jl-p-L{animation:jl-fly-L 1.35s cubic-bezier(.2,.85,.25,1.12) 0.75s both}
.jl-p-L img{animation:jl-depth-L 5.9s ease-in-out 2.4s infinite alternate}
@keyframes jl-fly-A{0%{transform:translate3d(470px,-120px,-760px) rotateX(20deg) rotateY(-115deg) rotateZ(35deg) scale(.35);opacity:0}35%{opacity:1}100%{transform:translate3d(0,0,0) rotateX(0) rotateY(0) rotateZ(0) scale(1);opacity:1}}
@keyframes jl-depth-A{0%{transform:translateZ(0)}100%{transform:translateZ(54px)}}
.jl-p-A{animation:jl-fly-A 1.35s cubic-bezier(.2,.85,.25,1.12) 0.9s both}
.jl-p-A img{animation:jl-depth-A 7.7s ease-in-out 2.4s infinite alternate}

.jl-wrap{position:relative;margin:0 auto;perspective:900px;perspective-origin:50% 40%}
.jl-stage{position:relative;width:100%;height:100%;transform-style:preserve-3d;animation:jl-float 7s ease-in-out 2.3s infinite alternate}
.jl-p{position:absolute;transform-style:preserve-3d;will-change:transform,opacity}
.jl-p img{display:block;width:100%;height:auto;transform-style:preserve-3d;user-select:none;-webkit-user-drag:none;pointer-events:none}
.jl-glow{position:absolute;left:8%;right:8%;top:12%;bottom:4%;border-radius:50%;background:radial-gradient(closest-side,rgba(255,69,0,.28),rgba(255,69,0,0));filter:blur(18px);opacity:0;animation:jl-glow-in 1.2s ease-out 1.7s forwards,jl-glow-pulse 5s ease-in-out 3s infinite alternate;pointer-events:none}
.jl-shadow{position:absolute;left:12%;right:12%;bottom:-14%;height:10%;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.22),rgba(0,0,0,0));opacity:0;animation:jl-glow-in 1s ease-out 1.8s forwards,jl-shadow 7s ease-in-out 2.3s infinite alternate;pointer-events:none}
@keyframes jl-float{0%{transform:rotateY(-14deg) rotateX(5deg) translateY(2px)}50%{transform:rotateY(2deg) rotateX(-3deg) translateY(-7px)}100%{transform:rotateY(14deg) rotateX(4deg) translateY(2px)}}
@keyframes jl-glow-in{to{opacity:1}}
@keyframes jl-glow-pulse{0%{transform:scale(.94)}100%{transform:scale(1.06)}}
@keyframes jl-shadow{0%{transform:scale(.92) translateX(-6px)}50%{transform:scale(1.04)}100%{transform:scale(.92) translateX(6px)}}
@media (prefers-reduced-motion:reduce){.jl-p,.jl-p img,.jl-stage,.jl-glow,.jl-shadow{animation:none!important;opacity:1!important}}
`;

export default function LogoIntro({ width = 250 }) {
  return (
    <div className="jl-wrap" style={{ width, height: width * LOGO_RATIO }} role="img" aria-label="جملة">
      <style>{CSS}</style>
      <div className="jl-glow" />
      <div className="jl-stage">
        {PIECES.map((p) => (
          <div
            key={p.k}
            className={`jl-p jl-p-${p.k}`}
            style={{ left: `${p.l}%`, top: `${p.t}%`, width: `${p.w}%` }}
          >
            <img src={p.src} alt="" draggable={false} />
          </div>
        ))}
      </div>
      <div className="jl-shadow" />
    </div>
  );
}
